    34  /* Returns true if the avail array AV[0]@COUNT is valid.
    35
    36     As a side effect, ensures the array is sorted by element size
    37     in increasing order and restores the ordering if necessary.
    38
    39     The proper ordering could have been clobbered in versions of GDBM<=1.15,
    40     by a call to _gdbm_put_av_elem with the can_merge parameter set to
    41     TRUE. This happened in two cases: either because the GDBM_COALESCEBLKS
    42     was set, and (quite unfortunately) when _gdbm_put_av_elem was called
    43     from pop_avail_block in falloc.c. The latter case is quite common,
    44     which means that there can be lots of existing databases with broken
    45     ordering of avail arrays. Thus, restoring of the proper ordering
    46     is essential for people to be able to use their existing databases.
    47  */
    48  static int
    49  gdbm_avail_table_valid_p (GDBM_FILE dbf, avail_elem *av, int count)
    50  {
    51    off_t prev = 0;
    52    int i;
    53    int needs_sorting = 0;
    54    avail_elem *p = av;
    55
    56    prev = 0;
    57    for (i = 0; i < count; i++, p++)
    58      {
    59        if (!(p->av_adr >= dbf->header->bucket_size
    60              && off_t_sum_ok (p->av_adr, p->av_size)
    61              && p->av_adr + p->av_size <= dbf->header->next_block))
    62          return 0;
    63        if (p->av_size < prev)
    64          needs_sorting = 1;
    65        prev = p->av_size;
    66      }
    67
    68    if (needs_sorting && dbf->read_write)
    69      {
    70        GDBM_DEBUG (GDBM_DEBUG_ERR, "%s", "restoring sort order");
    71        qsort (av, count, sizeof av[0], avail_comp);
    72      }
    73
    74    return 1;
    75  }
